1	<!DOCTYPE html>
2	<html lang="en" data-theme="light">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <title>Component catalog</title>
7	  <script src="../../project.config.js"></script>
8	  <style>
9	    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
10	
11	    :root {
12	      --cat-bg: #f9f9f9;
13	      --cat-surface: #ffffff;
14	      --cat-border: #e0e0e0;
15	      --cat-text: #1a1a1a;
16	      --cat-text-muted: #666666;
17	      --cat-accent: #2563eb;
18	      --cat-tag-atom: #d1fae5;
19	      --cat-tag-atom-text: #065f46;
20	      --cat-tag-molecule: #dbeafe;
21	      --cat-tag-molecule-text: #1e40af;
22	      --cat-tag-organism: #ede9fe;
23	      --cat-tag-organism-text: #4c1d95;
24	      --cat-tag-template: #fef3c7;
25	      --cat-tag-template-text: #92400e;
26	      --cat-sidebar-width: 220px;
27	      --cat-header-height: 56px;
28	    }
29	
30	    [data-theme="dark"] {
31	      --cat-bg: #111111;
32	      --cat-surface: #1c1c1e;
33	      --cat-border: #2e2e2e;
34	      --cat-text: #f0f0f0;
35	      --cat-text-muted: #888888;
36	      --cat-accent: #60a5fa;
37	      --cat-tag-atom: #064e3b;
38	      --cat-tag-atom-text: #6ee7b7;
39	      --cat-tag-molecule: #1e3a5f;
40	      --cat-tag-molecule-text: #93c5fd;
41	      --cat-tag-organism: #2e1065;
42	      --cat-tag-organism-text: #c4b5fd;
43	      --cat-tag-template: #451a03;
44	      --cat-tag-template-text: #fde68a;
45	    }
46	
47	    body {
48	      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
49	      font-size: 14px;
50	      background: var(--cat-bg);
51	      color: var(--cat-text);
52	      display: grid;
53	      grid-template-rows: var(--cat-header-height) 1fr;
54	      grid-template-columns: var(--cat-sidebar-width) 1fr;
55	      height: 100dvh;
56	      overflow: hidden;
57	    }
58	
59	    /* ── Header ──────────────────────────────────────────────────────────────── */
60	    header {
61	      grid-column: 1 / -1;
62	      display: flex;
63	      align-items: center;
64	      gap: 1rem;
65	      padding: 0 1.25rem;
66	      background: var(--cat-surface);
67	      border-bottom: 1px solid var(--cat-border);
68	    }
69	
70	    header h1 { font-size: 0.9rem; font-weight: 600; flex: 1; }
71	    header .subtitle { font-size: 0.75rem; color: var(--cat-text-muted); }
72	
73	    .theme-toggle {
74	      background: none;
75	      border: 1px solid var(--cat-border);
76	      border-radius: 6px;
77	      padding: 0.3rem 0.6rem;
78	      font-size: 0.75rem;
79	      color: var(--cat-text-muted);
80	      cursor: pointer;
81	    }
82	
83	    /* ── Sidebar ─────────────────────────────────────────────────────────────── */
84	    nav {
85	      overflow-y: auto;
86	      background: var(--cat-surface);
87	      border-right: 1px solid var(--cat-border);
88	      padding: 0.75rem 0;
89	    }
90	
91	    nav .section-label {
92	      font-size: 0.65rem;
93	      font-weight: 700;
94	      letter-spacing: 0.08em;
95	      text-transform: uppercase;
96	      color: var(--cat-text-muted);
97	      padding: 0.5rem 1rem 0.25rem;
98	    }
99	
100	    nav a {
101	      display: flex;
102	      align-items: center;
103	      gap: 0.5rem;
104	      padding: 0.35rem 1rem;
105	      font-size: 0.8rem;
106	      color: var(--cat-text);
107	      text-decoration: none;
108	      border-radius: 0;
109	      white-space: nowrap;
110	      overflow: hidden;
111	      text-overflow: ellipsis;
112	    }
113	
114	    nav a:hover { background: var(--cat-bg); }
115	    nav a.active { background: var(--cat-bg); color: var(--cat-accent); font-weight: 500; }
116	
117	    .tier-tag {
118	      display: inline-block;
119	      font-size: 0.6rem;
120	      font-weight: 600;
121	      text-transform: uppercase;
122	      letter-spacing: 0.04em;
123	      padding: 0.1rem 0.35rem;
