125	      flex-shrink: 0;
126	    }
127	
128	    .tier-atom     { background: var(--cat-tag-atom);     color: var(--cat-tag-atom-text); }
129	    .tier-molecule { background: var(--cat-tag-molecule); color: var(--cat-tag-molecule-text); }
130	    .tier-organism { background: var(--cat-tag-organism); color: var(--cat-tag-organism-text); }
131	    .tier-template { background: var(--cat-tag-template); color: var(--cat-tag-template-text); }
132	
133	    /* ── Main ────────────────────────────────────────────────────────────────── */
134	    main {
135	      overflow-y: auto;
136	      padding: 1.5rem 2rem;
137	    }
138	
139	    .catalog-home { max-width: 640px; }
140	    .catalog-home h2 { font-size: 1rem; font-weight: 600; margin-bottom: 0.5rem; }
141	    .catalog-home p { font-size: 0.85rem; color: var(--cat-text-muted); line-height: 1.6; margin-bottom: 1.5rem; }
142	
