155	      text-align: center;
156	    }
157	
158	    .stat strong { display: block; font-size: 1.4rem; font-weight: 700; }
159	    .stat span { font-size: 0.7rem; color: var(--cat-text-muted); text-transform: uppercase; letter-spacing: 0.06em; }
160	
161	    .tier-group h3 {
162	      font-size: 0.7rem;
163	      font-weight: 700;
164	      text-transform: uppercase;
