166	      color: var(--cat-text-muted);
167	      margin-bottom: 0.75rem;
168	      margin-top: 1.5rem;
169	      padding-bottom: 0.4rem;
170	      border-bottom: 1px solid var(--cat-border);
171	    }
172	
173	    .component-grid {
174	      display: grid;
175	      grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
176	      gap: 0.75rem;
177	      margin-bottom: 1rem;
178	    }
179	
180	    .component-card {
181	      background: var(--cat-surface);
182	      border: 1px solid var(--cat-border);
183	      border-radius: 8px;
184	      padding: 0.875rem 1rem;
185	      cursor: pointer;
186	      text-decoration: none;
187	      color: var(--cat-text);
188	      transition: border-color 0.1s;
189	    }
190	
191	    .component-card:hover { border-color: var(--cat-accent); }
192	
193	    .component-card .name { font-size: 0.85rem; font-weight: 500; margin-bottom: 0.25rem; }
194	    .component-card .element { font-size: 0.7rem; color: var(--cat-text-muted); font-family: monospace; }
195	
196	    /* ── Component detail ────────────────────────────────────────────────────── */
197	    .component-detail { max-width: 860px; }
198	    .component-detail h2 { font-size: 1.1rem; font-weight: 600; margin-bottom: 0.25rem; }
199	    .component-detail .meta { font-size: 0.75rem; color: var(--cat-text-muted); margin-bottom: 1.25rem; display: flex; gap: 0.75rem; align-items: center; }
200	
201	    .section { margin-bottom: 2rem; }
202	    .section h3 { font-size: 0.7rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.08em; color: var(--cat-text-muted); margin-bottom: 0.75rem; }
203	
204	    .demo-frame {
205	      background: var(--cat-surface);
206	      border: 1px solid var(--cat-border);
207	      border-radius: 8px;
208	      padding: 2rem;
209	      min-height: 120px;
210	    }
211	
212	    .demo-frame iframe {
213	      width: 100%;
214	      border: none;
215	      border-radius: 4px;
216	      display: block;
217	    }
218	
219	    .attributes-table {
220	      width: 100%;
221	      border-collapse: collapse;
222	      font-size: 0.8rem;
223	    }
224	
225	    .attributes-table th {
226	      text-align: left;
227	      font-size: 0.65rem;
228	      font-weight: 700;
229	      text-transform: uppercase;
230	      letter-spacing: 0.06em;
231	      color: var(--cat-text-muted);
232	      padding: 0.4rem 0.75rem;
233	      border-bottom: 1px solid var(--cat-border);
