240	    }
241	
242	    .attributes-table tr:last-child td { border-bottom: none; }
243	
244	    code {
245	      font-family: "SF Mono", Consolas, "Liberation Mono", monospace;
246	      font-size: 0.8em;
247	      background: var(--cat-bg);
248	      border: 1px solid var(--cat-border);
249	      border-radius: 3px;
250	      padding: 0.1em 0.35em;
251	    }
252	
253	    pre {
254	      background: var(--cat-bg);
255	      border: 1px solid var(--cat-border);
256	      border-radius: 8px;
257	      padding: 1rem;
258	      overflow-x: auto;
259	      font-size: 0.78rem;
260	      line-height: 1.6;
261	    }
262	
263	    pre code { background: none; border: none; padding: 0; }
264	
265	    .status-badge {
266	      font-size: 0.65rem;
267	      font-weight: 600;
268	      text-transform: uppercase;
269	      padding: 0.15rem 0.4rem;
270	      border-radius: 3px;
271	    }
272	
273	    .status-draft    { background: #fef9c3; color: #854d0e; }
274	    .status-in-review { background: #dbeafe; color: #1e40af; }
275	    .status-final    { background: #dcfce7; color: #166534; }
276	
277	    [data-theme="dark"] .status-draft     { background: #422006; color: #fde68a; }
278	    [data-theme="dark"] .status-in-review { background: #1e3a5f; color: #93c5fd; }
279	    [data-theme="dark"] .status-final     { background: #14532d; color: #bbf7d0; }
280	
281	    .empty-state {
282	      padding: 3rem 0;
283	      text-align: center;
284	      color: var(--cat-text-muted);
285	      font-size: 0.85rem;
286	    }
287	
288	    .empty-state code {
289	      display: block;
290	      margin: 0.75rem auto;
291	      width: fit-content;
292	    }
293	
294	    /* ── Login overlay ───────────────────────────────────────────── */
295	    #cat-login {
296	      position: fixed;
297	      inset: 0;
298	      z-index: 9999;
299	      background: var(--cat-bg);
300	      display: flex;
301	      align-items: center;
302	      justify-content: center;
303	    }
304	
305	    .cat-login-card {
306	      width: 420px;
307	      background: var(--cat-surface);
308	      border: 1px solid var(--cat-border);
309	      border-radius: 8px;
310	      padding: 2rem 1.75rem;
311	    }
312	
313	    .cat-login-title {
314	      font-size: 0.9rem;
315	      font-weight: 600;
316	      color: var(--cat-text);
317	      margin-bottom: 0.25rem;
318	    }
319	
320	    .cat-login-sub {
321	      font-size: 0.75rem;
322	      color: var(--cat-text-muted);
323	      margin-bottom: 1.25rem;
324	    }
325	
326	    #cat-password {
327	      width: 100%;
328	      background: var(--cat-bg);
329	      border: 1px solid var(--cat-border);
330	      border-radius: 6px;
331	      padding: 0.55rem 0.75rem;
332	      font-family: inherit;
333	      font-size: 0.85rem;
334	      color: var(--cat-text);
335	      outline: none;
336	      margin-bottom: 0.6rem;
337	      transition: border-color 0.15s;
338	    }
339	
340	    #cat-password:focus { border-color: var(--cat-accent); }
341	
342	    #cat-login-btn {
343	      width: 100%;
344	      background: var(--cat-text);
345	      color: var(--cat-surface);
346	      border: none;
347	      border-radius: 6px;
348	      padding: 0.55rem;
349	      font-family: inherit;
350	      font-size: 0.85rem;
351	      font-weight: 600;
352	      cursor: pointer;
353	      transition: opacity 0.15s;
354	    }
355	
356	    #cat-login-btn:hover { opacity: 0.85; }
357	
358	    #cat-login-err {
359	      font-size: 0.75rem;
360	      color: #d32f2f;
361	      margin-top: 0.5rem;
362	      display: none;
363	    }
364	  </style>
365	</head>
366	<body>
367	
368	<div id="cat-login" style="display:none">
369	  <div class="cat-login-card">
370	    <div class="cat-login-title">Component catalog</div>
371	    <div class="cat-login-sub">Enter password to continue.</div>
372	    <form id="cat-login-form" autocomplete="off">
373	      <input type="password" id="cat-password" placeholder="Password" required>
374	      <button type="submit" id="cat-login-btn">Enter</button>
375	      <div id="cat-login-err">Incorrect password. Try again.</div>
376	    </form>
377	  </div>
378	</div>
379	
380	<header>
381	  <h1 id="catalog-title">Component catalog</h1>
382	  <span class="subtitle" id="catalog-subtitle">Loading...</span>
383	  <button class="theme-toggle" onclick="toggleTheme()">Toggle theme</button>
384	</header>
385	
386	<nav id="sidebar"></nav>
387	
388	<main id="main"></main>
389	
390	<script type="module">
391	  // ── Contract import ─────────────────────────────────────────────────────────
392	  // Discovers the contract file relative to this catalog.
393	  // When deployed, this file sits at /catalog/index.html and the contract at
394	  // /library/contract/[prefix]-contract.js. Adjust the path if your folder
395	  // layout differs.
396	
397	  let contract = [];
398	  let prefix = 'ds';
399	
400	  const contractPaths = [
401	    '../library/contract/ds-contract.js',
402	  ];
403	
404	  async function loadContract() {
405	    for (const path of contractPaths) {
406	      try {
407	        const mod = await import(path);
408	        if (Array.isArray(mod.contract) && mod.contract.length) {
409	          contract = mod.contract;
410	          prefix = contract[0]?.prefix ?? 'ds';
411	          return true;
412	        }
413	      } catch {}
414	    }
415	    return false;
416	  }
417	
418	  // ── Routing ─────────────────────────────────────────────────────────────────
419	
420	  function getRoute() {
421	    const hash = location.hash.slice(1);
422	    return hash || null;
423	  }
424	
425	  function navigate(route) {
426	    location.hash = route ? '#' + route : '';
427	  }
428	
429	  // ── Render helpers ───────────────────────────────────────────────────────────
430	
431	  const TIERS = ['atom', 'molecule', 'organism', 'template'];
432	
433	  function byTier(tier) {
434	    return contract.filter(c => c.atomic === tier);
435	  }
436	
437	  function renderSidebar() {
438	    const nav = document.getElementById('sidebar');
439	    const route = getRoute();
440	    let html = `<a href="#" class="${!route ? 'active' : ''}">Overview</a>`;
441	
442	    for (const tier of TIERS) {
443	      const items = byTier(tier);
444	      if (!items.length) continue;
445	      html += `<div class="section-label">${cap(tier)}s</div>`;
446	      for (const c of items) {
447	        const active = route === c.element ? 'active' : '';
448	        html += `<a href="#${c.element}" class="${active}">
449	          <span class="tier-tag tier-${c.atomic}">${c.atomic[0]}</span>
450	          ${c.name}
451	        </a>`;
452	      }
453	    }
454	
455	    nav.innerHTML = html;
456	  }
457	
458	  function renderHome() {
459	    const main = document.getElementById('main');
460	
461	    if (!contract.length) {
462	      main.innerHTML = `<div class="catalog-home empty-state">
463	        <p>No components in the contract yet.</p>
464	        <p>Run <code>/extract</code> to populate the contract, then reload this page.</p>
465	      </div>`;
466	      return;
467	    }
468	
469	    const counts = TIERS.reduce((a, t) => { a[t] = byTier(t).length; return a; }, {});
470	
471	    let html = `<div class="catalog-home">
472	      <h2>Component library</h2>
473	      <p>Browsable reference for all components in this design system. Each entry links to its live demo page, documents the public API, and shows the usage snippet. Generated from <code>${prefix}-contract.js</code>.</p>
474	      <div class="stats">
475	        ${TIERS.map(t => `<div class="stat"><strong>${counts[t]}</strong><span>${t}s</span></div>`).join('')}
476	      </div>`;
477	
478	    for (const tier of TIERS) {
479	      const items = byTier(tier);
480	      if (!items.length) continue;
481	      html += `<div class="tier-group">
482	        <h3>${cap(tier)}s</h3>
483	        <div class="component-grid">`;
484	      for (const c of items) {
485	        html += `<a class="component-card" href="#${c.element}">
486	          <div class="name">${c.name}</div>
487	          <div class="element">&lt;${c.element}&gt;</div>
488	        </a>`;
489	      }
490	      html += `</div></div>`;
491	    }
492	
493	    html += `</div>`;
494	    main.innerHTML = html;
495	  }
496	
497	  function renderComponent(element) {
498	    const entry = contract.find(c => c.element === element);
499	    if (!entry) {
500	      renderHome();
501	      return;
502	    }
503	
504	    const demoPath = `../library/elements/${entry.name.toLowerCase()}/demo.html`;
505	    const jsPath = `../library/elements/${entry.name.toLowerCase()}/${entry.element}.js`;
506	
507	    const snippet = buildSnippet(entry);
508	
509	    const statusClass = 'status-' + (entry.status ?? 'draft').replace('-', '');
510	
511	    let html = `<div class="component-detail">
512	      <h2>${entry.name}</h2>
513	      <div class="meta">
514	        <code>&lt;${entry.element}&gt;</code>
515	        <span class="tier-tag tier-${entry.atomic}">${entry.atomic}</span>
516	        <span class="status-badge ${statusClass}">${entry.status ?? 'draft'}</span>
517	        <span>Extracted: ${entry.extracted ?? '-'}</span>
518	      </div>
519	
520	      <div class="section">
521	        <h3>Demo</h3>
522	        <div class="demo-frame">
523	          <iframe src="${demoPath}" id="demo-frame" onload="resizeFrame(this)"></iframe>
524	        </div>
525	      </div>
526	
527	      <div class="section">
528	        <h3>Usage</h3>
529	        <pre><code>${escHtml(snippet)}</code></pre>
530	      </div>`;
531	
532	    if (entry.attributes?.length) {
533	      html += `<div class="section">
534	        <h3>Attributes</h3>
535	        <table class="attributes-table">
536	          <thead><tr><th>Name</th><th>Type</th><th>Values</th><th>Default</th></tr></thead>
537	          <tbody>`;
538	      for (const attr of entry.attributes) {
539	        html += `<tr>
540	          <td><code>${attr.name}</code></td>
541	          <td>${attr.type}</td>
542	          <td>${attr.values ? attr.values.map(v => `<code>${v}</code>`).join(' ') : '—'}</td>
543	          <td><code>${attr.default ?? '-'}</code></td>
544	        </tr>`;
545	      }
546	      html += `</tbody></table></div>`;
547	    }
548	
549	    if (entry.slots?.length) {
550	      html += `<div class="section">
551	        <h3>Slots</h3>
552	        <table class="attributes-table">
553	          <thead><tr><th>Name</th><th>Description</th></tr></thead>
554	          <tbody>`;
555	      for (const slot of entry.slots) {
556	        html += `<tr>
557	          <td><code>${slot.name === 'default' ? '(default)' : slot.name}</code></td>
558	          <td>${slot.description ?? '-'}</td>
559	        </tr>`;
560	      }
561	      html += `</tbody></table></div>`;
562	    }
563	
564	    if (entry.composes?.length) {
565	      html += `<div class="section">
566	        <h3>Composes</h3>
567	        <p style="font-size:0.8rem;color:var(--cat-text-muted)">
568	          ${entry.composes.map(c => `<code>${c}</code>`).join(', ')}
569	        </p>
570	      </div>`;
571	    }
572	
573	    if (entry.a11y) {
574	      html += `<div class="section">
575	        <h3>Accessibility</h3>
576	        <p style="font-size:0.8rem;line-height:1.6">${entry.a11y}</p>
577	      </div>`;
578	    }
579	
580	    html += `<div class="section">
581	      <h3>Source</h3>
582	      <p style="font-size:0.8rem;color:var(--cat-text-muted)">
583	        <a href="${jsPath}" target="_blank">${jsPath}</a>
584	        &nbsp;·&nbsp;
585	        <a href="${demoPath}" target="_blank">demo.html</a>
586	      </p>
587	    </div>`;
588	
589	    html += `</div>`;
590	
591	    document.getElementById('main').innerHTML = html;
592	  }
593	
594	  function buildSnippet(entry) {
595	    const attrs = (entry.attributes ?? [])
596	      .filter(a => a.default !== false && a.default !== '' && a.default !== undefined)
597	      .map(a => {
598	        if (a.type === 'boolean') return a.default ? `  ${a.name}` : null;
599	        return `  ${a.name}="${a.default}"`;
600	      })
601	      .filter(Boolean)
602	      .join('\n');
603	
604	    const defaultSlot = (entry.slots ?? []).find(s => s.name === 'default');
605	    const inner = defaultSlot ? `\n  ${defaultSlot.description ?? 'Content'}\n` : '';
606	
607	    const opening = attrs
608	      ? `<${entry.element}\n${attrs}\n>`
609	      : `<${entry.element}>`;
610	
611	    return `${opening}${inner}</${entry.element}>`;
612	  }
613	
614	  function escHtml(str) {
615	    return str.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
616	  }
617	
618	  function cap(str) { return str[0].toUpperCase() + str.slice(1); }
619	
620	  // ── Frame resize ─────────────────────────────────────────────────────────────
621	  window.resizeFrame = function(iframe) {
622	    try {
623	      const h = iframe.contentDocument?.body?.scrollHeight;
624	      if (h) iframe.style.height = h + 'px';
625	    } catch {}
626	  };
627	
628	  // ── Theme ────────────────────────────────────────────────────────────────────
629	  window.toggleTheme = function() {
630	    const current = document.documentElement.getAttribute('data-theme');
631	    document.documentElement.setAttribute('data-theme', current === 'dark' ? 'light' : 'dark');
632	    localStorage.setItem('cat-theme', document.documentElement.getAttribute('data-theme'));
633	  };
634	
635	  const savedTheme = localStorage.getItem('cat-theme');
636	  if (savedTheme) document.documentElement.setAttribute('data-theme', savedTheme);
637	
638	  // ── Auth ─────────────────────────────────────────────────────────────────────
639	  function setupAuth(onPass) {
640	    const pw = window.PROJECT_CONFIG?.access?.password;
641	    const overlay = document.getElementById('cat-login');
642	
643	    if (!pw) { onPass(); return; }
644	
645	    overlay.style.display = 'flex';
646	
647	    document.getElementById('cat-login-form').addEventListener('submit', (e) => {
648	      e.preventDefault();
649	      const input = document.getElementById('cat-password').value;
650	      const err = document.getElementById('cat-login-err');
651	      if (input === pw) {
652	        overlay.style.display = 'none';
653	        onPass();
654	      } else {
655	        err.style.display = 'block';
656	        document.getElementById('cat-password').value = '';
657	        document.getElementById('cat-password').focus();
658	      }
659	    });
660	  }
661	
662	  // ── Boot ─────────────────────────────────────────────────────────────────────
663	  async function boot() {
664	    const loaded = await loadContract();
665	
666	    setupAuth(function () {
667	      const titleEl = document.getElementById('catalog-title');
668	      const subtitleEl = document.getElementById('catalog-subtitle');
669	
670	      titleEl.textContent = loaded
671	        ? `${prefix.toUpperCase()} component catalog`
672	        : 'Component catalog';
673	
674	      subtitleEl.textContent = loaded
675	        ? `${contract.length} component${contract.length !== 1 ? 's' : ''}`
676	        : 'No contract loaded yet';
677	
678	      function render() {
679	        const route = getRoute();
680	        renderSidebar();
681	        if (route) renderComponent(route);
682	        else renderHome();
683	      }
684	
685	      render();
686	      window.addEventListener('hashchange', render);
687	    });
688	  }
689	
690	  boot();
691	</script>
